"""Reproduce ticket #15467: radio_fields must not clobber a custom empty_label."""
import django
from django.conf import settings

settings.configure(
    DEBUG=True,
    DATABASES={"default": {"ENGINE": "django.db.backends.sqlite3", "NAME": ":memory:"}},
    INSTALLED_APPS=[
        "django.contrib.contenttypes",
        "django.contrib.auth",
        "django.contrib.admin",
        "django.contrib.messages",
    ],
    TEMPLATES=[{
        "BACKEND": "django.template.backends.django.DjangoTemplates",
        "DIRS": [],
        "APP_DIRS": True,
        "OPTIONS": {"context_processors": [
            "django.contrib.auth.context_processors.auth",
            "django.contrib.messages.context_processors.messages",
        ]},
    }],
    ROOT_URLCONF=None,
)
django.setup()

from django.contrib import admin
from django.db import models

class Band(models.Model):
    name = models.CharField(max_length=100)

    class Meta:
        app_label = "repro"

class Concert(models.Model):
    main_band = models.ForeignKey(Band, models.CASCADE, blank=True, null=True)

    class Meta:
        app_label = "repro"

CUSTOM = "I WANT TO SET MY OWN EMPTY LABEL"

class ConcertAdmin(admin.ModelAdmin):
    radio_fields = {"main_band": admin.VERTICAL}

    def formfield_for_foreignkey(self, db_field, request, **kwargs):
        if db_field.name == "main_band":
            kwargs["empty_label"] = CUSTOM
        return super().formfield_for_foreignkey(db_field, request, **kwargs)

site = admin.AdminSite()
ma = ConcertAdmin(Concert, site)
ff = ma.formfield_for_foreignkey(Concert._meta.get_field("main_band"), request=None)
label = ff.empty_label
print("empty_label =", repr(label))
assert label == CUSTOM, f"BUG STILL PRESENT: got {label!r}, wanted {CUSTOM!r}"

# Also check the default path is unchanged: no custom label -> 'None'
class ConcertAdmin2(admin.ModelAdmin):
    radio_fields = {"main_band": admin.VERTICAL}

ma2 = ConcertAdmin2(Concert, site)
ff2 = ma2.formfield_for_foreignkey(Concert._meta.get_field("main_band"), request=None)
print("default empty_label =", repr(ff2.empty_label))
assert str(ff2.empty_label) == "None", f"default label changed: {ff2.empty_label!r}"

# blank=False field must still get empty_label None
class Gig(models.Model):
    main_band = models.ForeignKey(Band, models.CASCADE)

    class Meta:
        app_label = "repro"

class GigAdmin(admin.ModelAdmin):
    radio_fields = {"main_band": admin.VERTICAL}

ma3 = GigAdmin(Gig, site)
ff3 = ma3.formfield_for_foreignkey(Gig._meta.get_field("main_band"), request=None)
print("blank=False empty_label =", repr(ff3.empty_label))
assert ff3.empty_label is None

print("ALL CHECKS PASSED")

